public class Main{static long xsNext(long x){x^=x<<13;x^=x>>>7;x^=x<<17;return x;}public static void main(String[]a){java.util.ArrayList<int[]> items=new java.util.ArrayList<>(1000000);java.util.ArrayList<Integer> marks=new java.util.ArrayList<>();long r=12345;for(int i=0;i<1000000;i++){r=xsNext(r);items.add(new int[]{(int)Long.remainderUnsigned(r,1000000),i%97});if(i%64==0)marks.add(items.size()-1);}long total=0,mt=0;for(int[]it:items)total+=it[0];for(int m:marks)mt+=items.get(m)[1];System.out.println(items.size());System.out.println(marks.size());System.out.println(Long.toUnsignedString(total));System.out.println(Long.toUnsignedString(mt));}}